style.css:
/* Hide all images */
img {
    display: none !important;
    pointer-events: none !important;
}

/* Disable clicking on links to images */
a[href*="openai.com"] {
    pointer-events: none !important;
    cursor: default !important;
    text-decoration: none !important;
    color: inherit !important;
}

/* Attempt to hide preview popups (dynamic overlays) */
div[role="dialog"] img {
    display: none !important;
}

div[role="dialog"] {
    pointer-events: none !important;  /* disable interaction with overlay */
}

/* Extra precaution: hide background image previews */
div[style*="background-image"] {
    background-image: none !important;
}
